// Static-data fallback so the web app renders the full hero experience with NO backend
// (the public Vercel deploy). When a live API is configured the client prefers it and
// uses these only as a fallback. Assets live in /public/hero, generated by
// `python -m lithos_ingest.export_web_assets`.

import type {
  AoiScanResult,
  CoverageProperties,
  FeatureCollection,
  HeroDescriptor,
  PointProperties,
  PointVerdict,
  TimeSeries,
} from "./types";

type PointFC = FeatureCollection<{ type: "Point"; coordinates: [number, number] }, PointProperties>;
type CoverageFC = FeatureCollection<{ type: "Polygon"; coordinates: number[][][] }, CoverageProperties>;

let _pointsCache: PointFC | null = null;
let _verdictsCache: Record<string, PointVerdict> | null = null;
let _tsCache: { dates: string[]; series: Record<string, (number | null)[]> } | null = null;

async function loadJson<T>(path: string): Promise<T> {
  const res = await fetch(path, { headers: { Accept: "application/json" } });
  if (!res.ok) throw new Error(`static asset ${path} -> ${res.status}`);
  return res.json() as Promise<T>;
}

async function points(): Promise<PointFC> {
  if (_pointsCache) return _pointsCache;
  const fc = await loadJson<PointFC>("/hero/points.geojson");
  _pointsCache = fc;
  return fc;
}

async function verdicts(): Promise<Record<string, PointVerdict>> {
  if (_verdictsCache) return _verdictsCache;
  const v = await loadJson<Record<string, PointVerdict>>("/hero/verdicts.json");
  _verdictsCache = v;
  return v;
}

async function timeseriesBlob(): Promise<{ dates: string[]; series: Record<string, (number | null)[]> }> {
  if (_tsCache) return _tsCache;
  const blob = await loadJson<{ dates: string[]; series: Record<string, (number | null)[]> }>(
    "/hero/timeseries.json",
  );
  _tsCache = blob;
  return blob;
}

function inPolygon(lon: number, lat: number, ring: number[][]): boolean {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const xi = ring[i][0];
    const yi = ring[i][1];
    const xj = ring[j][0];
    const yj = ring[j][1];
    const intersect =
      yi > lat !== yj > lat && lon < ((xj - xi) * (lat - yi)) / (yj - yi || 1e-12) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

// Flags that say nothing changed and nothing clear is happening.
const QUIET = ["stable", "inconclusive"];

export const staticData = {
  hero: () => loadJson<HeroDescriptor>("/hero/hero.json"),

  coverageGrid: () => loadJson<CoverageFC>("/hero/coverage_grid.geojson"),

  points: async (withAnomaly: boolean): Promise<PointFC> => {
    const fc = await points();
    if (withAnomaly) return fc;
    // Strip anomaly props for the fast first-paint parity with the API.
    return {
      type: "FeatureCollection",
      features: fc.features.map((f) => ({
        ...f,
        properties: {
          ...f.properties,
          anomaly_type: null,
          headline: null,
        },
      })),
    };
  },

  anomalies: async (): Promise<PointFC> => {
    const fc = await points();
    const notable = fc.features.filter(
      (f) => f.properties.anomaly_type && !QUIET.includes(f.properties.anomaly_type),
    );
    notable.sort((a, b) => (b.properties.newsworthiness ?? 0) - (a.properties.newsworthiness ?? 0));
    return {
      type: "FeatureCollection",
      features: notable,
      summary: { queried: fc.features.length, notable: notable.length },
    };
  },

  timeSeries: async (pointId: string): Promise<TimeSeries> => {
    const blob = await timeseriesBlob();
    const disp = blob.series[pointId] ?? [];
    return {
      point_id: pointId,
      samples: blob.dates.map((d, i) => ({
        date: d,
        displacement_mm: disp[i] ?? null,
        uncertainty_mm: null,
      })),
    };
  },

  verdict: async (pointId: string): Promise<PointVerdict> => {
    const all = await verdicts();
    const v = all[pointId];
    if (v) return v;
    return { point_id: pointId, velocity_mm_yr: null, velocity_uncertainty_mm_yr: null, flags: [], headline: "", newsworthiness: 0 };
  },

  // Client-side AOI aggregate. Spatial Gi* clustering needs the engine, so static mode
  // reports stats honestly and notes that clusters require a live API.
  scanAoi: async (polygon: { type: "Polygon"; coordinates: number[][][] }): Promise<AoiScanResult> => {
    const fc = await points();
    const ring = polygon.coordinates[0];
    const inside = fc.features.filter((f) => {
      const [lon, lat] = f.geometry.coordinates;
      return inPolygon(lon, lat, ring);
    });
    if (inside.length === 0) {
      return { point_count: 0, note: "No indexed ground-motion points in this area." };
    }
    const vels = inside.map((f) => f.properties.best_velocity ?? 0);
    const anomalous = inside.filter(
      (f) =>
        f.properties.anomaly_type &&
        !QUIET.includes(f.properties.anomaly_type) &&
        f.properties.anomaly_type !== "steady_motion",
    ).length;
    const top = [...inside]
      .sort((a, b) => (b.properties.newsworthiness ?? 0) - (a.properties.newsworthiness ?? 0))
      .slice(0, 8)
      .map((f) => ({
        point_id: f.properties.id,
        velocity_mm_yr: f.properties.best_velocity,
        velocity_uncertainty_mm_yr: f.properties.velocity_uncertainty,
        flags: [],
        headline: f.properties.headline ?? "",
        newsworthiness: f.properties.newsworthiness ?? 0,
      }));
    return {
      point_count: inside.length,
      anomalous_count: anomalous,
      mean_velocity_mm_yr: vels.reduce((a, b) => a + b, 0) / vels.length,
      max_subsidence_mm_yr: Math.min(...vels),
      max_uplift_mm_yr: Math.max(...vels),
      cluster_flags: [],
      top_points: top,
      note: "Cluster detection needs the LITHOS API; this page serves stored results.",
    };
  },
};
